<?php

declare(strict_types=1);

namespace App\Hosts\Protocol;

use App\Attributes\AutoGenerated;
use Spatie\LaravelData\Data;

/**
 * Every call the host makes to the journal in host protocol 1, by its name.
 * Generated by php artisan journal:host-protocol from protocol/host.json; do not edit.
 */
#[AutoGenerated('protocol/host.json')]
enum HostRoute: string
{
    case ClaimInstructions = 'claim_instructions';
    case AnswerInstructions = 'answer_instructions';
    case PullPrivateValue = 'pull_private_value';
    case NotifyProcessOutput = 'notify_process_output';
    case NotifyProcessReport = 'notify_process_report';
    case NotifyInventory = 'notify_inventory';
    case NotifyHeartbeat = 'notify_heartbeat';
    case NotifyProjectRead = 'notify_project_read';

    /**
     * Whether the path, without its query, is this call's.
     */
    public function matchesPath(string $path): bool
    {
        return preg_match(match ($this) {
            self::ClaimInstructions => '#^/host/instructions/claim$#',
            self::AnswerInstructions => '#^/host/instructions/[^/]+$#',
            self::PullPrivateValue => '#^/host/private\-values/[^/]+$#',
            self::NotifyProcessOutput => '#^/host/processes/[^/]+/output$#',
            self::NotifyProcessReport => '#^/host/processes/[^/]+$#',
            self::NotifyInventory => '#^/host/inventory$#',
            self::NotifyHeartbeat => '#^/host/heartbeat$#',
            self::NotifyProjectRead => '#^/host/reports/project\-reads/[^/]+$#',
        }, $path) === 1;
    }

    /**
     * The Data of the body the host sends with this call.
     *
     * @return class-string<Data>
     */
    public function bodyPayload(): string
    {
        return match ($this) {
            self::ClaimInstructions => Payloads\HostEmptyPayload::class,
            self::AnswerInstructions => Payloads\HostAnswerPayload::class,
            self::PullPrivateValue => Payloads\HostEmptyPayload::class,
            self::NotifyProcessOutput => Payloads\HostOutputPayload::class,
            self::NotifyProcessReport => Payloads\HostProcessReportPayload::class,
            self::NotifyInventory => Payloads\HostInventoryPayload::class,
            self::NotifyHeartbeat => Payloads\HostHeartbeatPayload::class,
            self::NotifyProjectRead => Payloads\HostProjectReadReportPayload::class,
        };
    }

    /**
     * The Data of the journal's answer to this call.
     *
     * @return class-string<Data>
     */
    public function replyPayload(): string
    {
        return match ($this) {
            self::ClaimInstructions => Payloads\HostClaimedInstructionsPayload::class,
            self::AnswerInstructions => Payloads\HostEmptyPayload::class,
            self::PullPrivateValue => Payloads\HostPrivateValuePayload::class,
            self::NotifyProcessOutput => Payloads\HostEmptyPayload::class,
            self::NotifyProcessReport => Payloads\HostEmptyPayload::class,
            self::NotifyInventory => Payloads\HostEmptyPayload::class,
            self::NotifyHeartbeat => Payloads\HostEmptyPayload::class,
            self::NotifyProjectRead => Payloads\HostEmptyPayload::class,
        };
    }
}
